def evaluate_goal(task, trajectory):
    hard = run_hard_checks(task.done_when)   # 程序化:产物/行为/约束
    if not hard.passed:
        return {"goal": False, "reason": hard.failures}
    soft = judge_score(                       # 软判据:judge 按任务描述评
        trajectory.final_output,
        task_description=task.goal,
        rubric=task.soft_rubric)
    return {"goal": soft.score >= THRESHOLD,
            "hard": hard.summary, "soft": soft.breakdown}
```

